xpath.script:
// Get translated strings from hidden elements
function getTranslation(key) {
    const element = document.getElementById('trans-' + key);
    return element ? element.textContent : key;
}

// Custom notification function to replace alert
function showNotification(message, type = 'danger', duration = 5000) {
    const notificationArea = document.getElementById('notification-area');

    // Create notification element
    const notification = document.createElement('div');
    notification.className = `alert alert-${type} alert-dismissible fade show mt-2`;
    notification.setAttribute('role', type === 'danger' ? 'alert' : 'status');
    notification.innerHTML = `
        ${message}
        <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="${getTranslation('close')}"></button>
    `;

    // Add to notification area
    notificationArea.appendChild(notification);

    // Auto-remove after duration
    setTimeout(() => {
        if (notification.parentNode) {
            notification.classList.remove('show');
            setTimeout(() => {
                if (notification.parentNode) {
                    notification.parentNode.removeChild(notification);
                }
            }, 150);
        }
    }, duration);
}

function startTimer() {
    const timerDisplay = document.getElementById('timerDisplay');
    const resendOtpBtn = document.getElementById('resendOtpBtn');
    let timeLeft = 300; // 5 minutes in seconds

    resendOtpBtn.style.display = 'none';

    const timer = setInterval(function() {
        const minutes = Math.floor(timeLeft / 60);
        const seconds = timeLeft % 60;

        timerDisplay.textContent = getTranslation('resend-otp-in') + ' ' + minutes + ':' + seconds.toString().padStart(2, '0');

        if (timeLeft <= 0) {
            clearInterval(timer);
            timerDisplay.textContent = '';
            resendOtpBtn.style.display = 'block';
        }
        timeLeft -= 1;
    }, 1000);
}

function handleSendMobile(button) {
    if (!button) return;

    const form = button.form;
    const mobileInput = document.getElementById('mobile');

    if (!mobileInput) {
        console.error('Mobile input not found');
        return;
    }

    // Validate mobile number
    if (!mobileInput.value.trim()) {
        showNotification(getTranslation('please-enter-mobile'), 'warning');
        mobileInput.focus();
        return;
    }

    // Basic mobile number validation
    const mobilePattern = /^[0-9]{10,15}$/;
    if (!mobilePattern.test(mobileInput.value.trim())) {
        showNotification(getTranslation('please-enter-valid-mobile'), 'warning');
        mobileInput.focus();
        return;
    }

    setLoadingState(button, true);
    mobileInput.readOnly = true;

    if (form && form.submitted_action) {
        form.submitted_action.value = 'send_mobile';
        form.submit();
    }
}

function handleAuthorizeOtp(button) {
    if (!button) {
        console.error('Button is null');
        return;
    }

    const form = button.closest('form');
    const mobileInput = document.getElementById('mobile');
    const nationalInput = document.getElementById('national_code');
    const birthdateInput = document.getElementById('birthdate');

    console.log('handleAuthorizeOtp called', {button, form, mobileInput, nationalInput, birthdateInput});

    if (!mobileInput || !nationalInput || !birthdateInput) {
        console.error('Required inputs not found');
        return;
    }

    // Validate national code using checkCodeMeli
    const nationalVal = nationalInput.value.trim();
    if (!checkCodeMeli(nationalVal)) {
        showNotification(getTranslation('please-enter-valid-national-code') || 'National code must be 10 digits', 'warning');
        nationalInput.focus();
        return;
    }

    // Validate birthdate
    if (!birthdateInput.value) {
        showNotification(getTranslation('please-enter-birthdate') || 'Birthdate is required', 'warning');
        birthdateInput.focus();
        return;
    }

    console.log('Validation passed, setting loading state');

    mobileInput.readOnly = true;
    nationalInput.readOnly = true;
    birthdateInput.readOnly = true;

    if (form && form.submitted_action) {
        form.submitted_action.value = 'authorize_otp';
        setLoadingState(button, true);
        console.log('Submitting form');
        form.submit();
    } else {
        console.error('Form or submitted_action not found', {form});
    }
}

function handleVerifyOtp(button) {
    if (!button) {
        console.error('Button is null');
        return;
    }

    const form = button.closest('form');
    const otpInput = document.getElementById('otp');
    const mobileInput = document.getElementById('mobile');

    console.log('handleVerifyOtp called', {button, form, otpInput, mobileInput});

    if (!otpInput || !mobileInput) {
        console.error('OTP or mobile input not found');
        return;
    }

    // Validate OTP
    if (!otpInput.value.trim()) {
        showNotification(getTranslation('please-enter-otp'), 'warning');
        otpInput.focus();
        return;
    }

    // Basic OTP validation (should be 6 digits)
    const otpPattern = /^[0-9]{6}$/;
    if (!otpPattern.test(otpInput.value.trim())) {
        showNotification(getTranslation('please-enter-valid-otp'), 'warning');
        otpInput.focus();
        return;
    }

    console.log('Validation passed, setting loading state');

    otpInput.readOnly = true;
    mobileInput.readOnly = true;

    if (form && form.submitted_action) {
        form.submitted_action.value = 'verify_otp';
        setLoadingState(button, true);
        console.log('Submitting form');
        form.submit();
    } else {
        console.error('Form or submitted_action not found', {form});
    }
}

function setLoadingState(button, isLoading) {
    if (!button) {
        console.error('setLoadingState: button is null');
        return;
    }

    console.log('setLoadingState called', {button, isLoading, innerHTML: button.innerHTML});

    if (isLoading) {
        button.disabled = true;
        // Simply hide all text and show spinner by clearing innerHTML and using a spinner
        const originalHTML = button.innerHTML;
        button.innerHTML = '<span class="spinner-border spinner-border-sm" role="status" aria-hidden="true"></span>';
        button.dataset.originalHTML = originalHTML;
        console.log('Loading state set to true - SUCCESS');
    } else {
        button.disabled = false;
        // Restore original HTML
        if (button.dataset.originalHTML) {
            button.innerHTML = button.dataset.originalHTML;
            delete button.dataset.originalHTML;
        }
        console.log('Loading state set to false - SUCCESS');
    }
}

// Iranian national code validation
function checkCodeMeli(code) {
    if (!code) return false;
    var L = code.length;
    if (L < 8 || parseInt(code, 10) === 0) return false;
    code = ('0000' + code).substr(L + 4 - 10);
    if (parseInt(code.substr(3, 6), 10) === 0) return false;
    var c = parseInt(code.substr(9, 1), 10);
    var s = 0;
    for (var i = 0; i < 9; i++)
        s += parseInt(code.substr(i, 1), 10) * (10 - i);
    s = s % 11;
    return (s < 2 && c == s) || (s >= 2 && c == (11 - s));
}

document.addEventListener('DOMContentLoaded', function() {
    // Only keep the toggle functionality in JavaScript
    const otpSection = document.getElementById('otp_section');
    const passwordSection = document.getElementById('password_section');
    const otpLogin = document.getElementById('otp_login');
    const pwdLogin = document.getElementById('pwd_login');

    otpLogin.addEventListener('change', function() {
        otpSection.style.display = 'block';
        passwordSection.style.display = 'none';
        // Clear any existing notifications when switching
        document.getElementById('notification-area').innerHTML = '';
    });

    pwdLogin.addEventListener('change', function() {
        otpSection.style.display = 'none';
        passwordSection.style.display = 'block';
        // Clear any existing notifications when switching
        document.getElementById('notification-area').innerHTML = '';
    });

    // Add input event listeners for better UX
    const mobileInput = document.getElementById('mobile');
    const otpInput = document.getElementById('otp');

    if (mobileInput) {
        mobileInput.addEventListener('input', function() {
            // Remove readonly when user starts typing again
            if (this.readOnly) {
                this.readOnly = false;
            }
        });
    }

    if (otpInput) {
        otpInput.addEventListener('input', function() {
            // Remove readonly when user starts typing again
            if (this.readOnly) {
                this.readOnly = false;
            }
            // Auto-format OTP input (only numbers)
            this.value = this.value.replace(/[^0-9]/g, '');
        });
    }
});

// Start timer when OTP is sent
if (document.getElementById('timerDisplay') && "<t t-esc=\"request.params.get('otp_sent')\"/>" === "True") {
    startTimer();
}
